mapper.select:
SELECT account_id, state_date, draw_pile_json, discard_pile_json, active_round_json, updated_at
FROM pet_flip7_states
WHERE account_id = #{accountId}

mapper.insert:
INSERT INTO pet_flip7_states (
    account_id, state_date, draw_pile_json, discard_pile_json, active_round_json, updated_at
) VALUES (
    #{accountId}, #{stateDate}, #{drawPileJson}, #{discardPileJson}, #{activeRoundJson}, #{updatedAt}
)
ON CONFLICT(account_id) DO UPDATE
SET state_date = #{stateDate},
    draw_pile_json = #{drawPileJson},
    discard_pile_json = #{discardPileJson},
    active_round_json = #{activeRoundJson},
    updated_at = #{updatedAt}
